SELECT json_build_object('at',clock_timestamp(),'database_bytes',pg_database_size(current_database()),'relations',(SELECT json_agg(x) FROM (SELECT n.nspname AS schema,c.relname AS relation,pg_relation_size(c.oid) AS heap_main_bytes,pg_table_size(c.oid) AS table_including_toast_forks_bytes,CASE WHEN c.reltoastrelid=0 THEN 0 ELSE pg_total_relation_size(c.reltoastrelid) END AS toast_total_including_index_bytes,pg_indexes_size(c.oid) AS table_indexes_bytes,pg_total_relation_size(c.oid) AS total_bytes FROM pg_class c JOIN pg_namespace n ON n.oid=c.relnamespace WHERE n.nspname IN ('bench_jsonb','bench_arrays','bench_bytes') AND c.relkind='r' ORDER BY 1,2) x));
